begin;
create table public.permisos_operativos(id_usuario uuid primary key references public.perfiles on delete cascade,aprobar_receta boolean not null default false,confirmar_pago boolean not null default false,aprobar_stock boolean not null default false,modificar_precio boolean not null default false);
insert into public.permisos_operativos select id_usuario,rol in ('ADMIN','GERENTE','VENDEDOR'),rol in ('ADMIN','GERENTE','VENDEDOR','CAJERO'),rol in ('ADMIN','GERENTE'),rol='ADMIN' from public.perfiles;
create function privado.crear_permisos() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin insert into public.permisos_operativos values(new.id_usuario,new.rol in ('ADMIN','GERENTE','VENDEDOR'),new.rol in ('ADMIN','GERENTE','VENDEDOR','CAJERO'),new.rol in ('ADMIN','GERENTE'),new.rol='ADMIN') on conflict do nothing;return new;end $$;
create trigger crear_permisos after insert on public.perfiles for each row execute function privado.crear_permisos();
alter table public.permisos_operativos enable row level security;
grant select,update on public.permisos_operativos to authenticated;
grant all on public.permisos_operativos to service_role;
create policy leer on public.permisos_operativos for select to authenticated using(id_usuario=auth.uid() or privado.permitido(array['ADMIN']));
create policy editar on public.permisos_operativos for update to authenticated using(privado.permitido(array['ADMIN'])) with check(privado.permitido(array['ADMIN']));
create trigger historial after update on public.permisos_operativos for each row execute function privado.auditar('id_usuario');
create function privado.exigir_permiso(p_nombre text) returns void language plpgsql security definer set search_path=pg_catalog,public as $$begin
 if not exists(select 1 from public.perfiles p join public.permisos_operativos o using(id_usuario) where p.id_usuario=auth.uid() and p.activo and (p.rol='ADMIN' or (to_jsonb(o)->>p_nombre)::boolean)) then raise exception 'Tu cuenta no tiene autorización para esta acción' using errcode='42501';end if;
end $$;
revoke all on function privado.exigir_permiso(text) from public,anon,authenticated;
do $$ declare d text;begin
 d:=pg_get_functiondef('public.gestionar_pedido_portal(bigint,text,jsonb)'::regprocedure);d:=replace(d,'if p_accion=''receta'' then','if p_accion=''receta'' then perform privado.exigir_permiso(''aprobar_receta'');');d:=replace(d,'elsif p_accion=''pago'' then','elsif p_accion=''pago'' then perform privado.exigir_permiso(''confirmar_pago'');');execute d;
 d:=pg_get_functiondef('privado.ajuste(jsonb)'::regprocedure);d:=replace(d,'begin','begin perform privado.exigir_permiso(''aprobar_stock'');');execute d;
end $$;
create table public.compras(id_compra bigint generated by default as identity primary key,id_proveedor bigint not null references public.proveedores,id_sucursal bigint not null references public.sucursales,estado text not null default 'PENDIENTE',factura varchar(100),total numeric(14,2) not null,pagado numeric(14,2) not null default 0,creado_en timestamptz not null default now(),creado_por uuid references auth.users,unique(id_proveedor,factura));
create table public.detalle_compra(id_detalle bigint generated by default as identity primary key,id_compra bigint not null references public.compras,id_medicamento bigint not null references public.medicamentos,cantidad integer not null check(cantidad>0),costo numeric(12,2) not null check(costo>=0),recibido integer not null default 0 check(recibido>=0 and recibido<=cantidad),unique(id_compra,id_medicamento));
create table public.solicitudes_stock(id_solicitud bigint generated by default as identity primary key,id_sucursal bigint not null references public.sucursales,id_inventario bigint not null references public.inventario,tipo text not null check(tipo in ('CONTEO','BAJA','DEV_PROVEEDOR')),cantidad integer not null check(cantidad>=0),existencia_observada integer not null,motivo varchar(255) not null,estado text not null default 'PENDIENTE',solicitado_por uuid references auth.users,aprobado_por uuid references auth.users,creado_en timestamptz not null default now());
create table public.devoluciones_clientes(id_devolucion bigint generated by default as identity primary key,id_sucursal bigint not null references public.sucursales,id_detalle bigint not null references public.detalle_venta,cantidad integer not null check(cantidad>0),reembolso numeric(12,2) not null check(reembolso>=0),motivo varchar(255) not null,destino text not null default 'CUARENTENA',creado_en timestamptz not null default now());
create table public.cierres_caja(id_cierre bigint generated by default as identity primary key,id_sucursal bigint not null references public.sucursales,desde timestamptz not null,hasta timestamptz not null,esperado numeric(14,2) not null,contado numeric(14,2) not null check(contado>=0),diferencia numeric(14,2) not null,nota varchar(255) not null,creado_por uuid references auth.users,creado_en timestamptz not null default now(),check(hasta>desde));
create table privado.operaciones_farmacia(clave uuid primary key,actor uuid not null,accion text not null,datos jsonb not null,respuesta jsonb not null);
revoke all on privado.operaciones_farmacia from public,anon,authenticated;
do $$ declare t text;pk text;begin
 for t,pk in select * from(values('compras','id_compra'),('solicitudes_stock','id_solicitud'),('devoluciones_clientes','id_devolucion'),('cierres_caja','id_cierre'))v(t,pk) loop
 execute format('alter table public.%I enable row level security',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy leer on public.%I for select to authenticated using(privado.permitido(%L::text[],id_sucursal))',t,case t when 'compras' then '{GERENTE,BODEGA,CAJERO,AUDITOR}' when 'solicitudes_stock' then '{GERENTE,BODEGA,AUDITOR}' when 'cierres_caja' then '{GERENTE,CAJERO,AUDITOR}' else '{GERENTE,AUDITOR}' end);execute format('create trigger historial after insert or update on public.%I for each row execute function privado.auditar(%L)',t,pk);end loop;
end $$;
alter table public.detalle_compra enable row level security;grant select on public.detalle_compra to authenticated;
create policy leer on public.detalle_compra for select to authenticated using(exists(select 1 from public.compras c where c.id_compra=detalle_compra.id_compra));
create function privado.no_anular_con_devolucion() returns trigger language plpgsql set search_path=pg_catalog,public as $$begin
 if new.estado='ANULADA' and exists(select 1 from public.devoluciones_clientes d join public.detalle_venta v using(id_detalle) where v.id_venta=new.id_venta) then raise exception 'La venta ya tiene devoluciones; no se puede anular completa' using errcode='P0001';end if;return new;end $$;
create trigger impedir_doble_reembolso before update on public.ventas for each row execute function privado.no_anular_con_devolucion();
create function public.operar_farmacia(p_accion text,p_datos jsonb,p_clave uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare anterior privado.operaciones_farmacia;c public.compras;dc public.detalle_compra;sol public.solicitudes_stock;inv public.inventario;dv public.detalle_venta;v public.ventas;item jsonb;id bigint;sucursal bigint;monto numeric;delta integer;resultado jsonb;neto numeric;envio numeric;pagos text;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_clave::text,0));select * into anterior from privado.operaciones_farmacia where clave=p_clave;
 if found then if anterior.actor is distinct from auth.uid() or anterior.accion<>p_accion or anterior.datos<>p_datos then raise exception 'La operación ya corresponde a otra solicitud' using errcode='P0001';end if;return anterior.respuesta;end if;
 if p_accion in ('compra_crear','compra_recibir') then
  if jsonb_typeof(p_datos->'items') is distinct from 'array' or jsonb_array_length(p_datos->'items') not between 1 and 50 then raise exception 'Agrega entre 1 y 50 productos' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_datos->'items') i group by i->>'id_medicamento' having count(*)>1) then raise exception 'No repitas productos' using errcode='22023';end if;
  for item in select value from jsonb_array_elements(p_datos->'items') loop
   if coalesce((item->>'cantidad')::numeric,0) not between 1 and 1000000 or (item->>'cantidad')::numeric<>trunc((item->>'cantidad')::numeric) then raise exception 'Cantidad inv?lida' using errcode='22023';end if;
   if p_accion='compra_crear' and (item->>'costo' is null or (item->>'costo')::numeric not between 0 and 999999999 or round((item->>'costo')::numeric,2)<>(item->>'costo')::numeric) then raise exception 'Costo inv?lido' using errcode='22023';end if;
  end loop;
 end if;
 if p_accion='compra_pagar' and (coalesce((p_datos->>'monto')::numeric,0)<=0 or round((p_datos->>'monto')::numeric,2)<>(p_datos->>'monto')::numeric) then raise exception 'Monto inv?lido' using errcode='22023';end if;
 if p_accion='devolucion_cliente' and (coalesce((p_datos->>'cantidad')::numeric,0)<=0 or (p_datos->>'cantidad')::numeric<>trunc((p_datos->>'cantidad')::numeric)) then raise exception 'Cantidad inv?lida' using errcode='22023';end if;
 if p_accion='compra_crear' then
  sucursal:=(p_datos->>'id_sucursal')::bigint;perform privado.exigir(array['GERENTE','BODEGA'],sucursal);
  if not exists(select 1 from proveedores where id_proveedor=(p_datos->>'id_proveedor')::bigint and activo) then raise exception 'Proveedor inactivo o inexistente' using errcode='22023';end if;
  monto:=0;for item in select value from jsonb_array_elements(p_datos->'items') loop monto:=monto+(item->>'cantidad')::integer*(item->>'costo')::numeric;end loop;
  insert into public.compras(id_proveedor,id_sucursal,total,creado_por) values((p_datos->>'id_proveedor')::bigint,sucursal,monto,auth.uid()) returning id_compra into id;
  for item in select value from jsonb_array_elements(p_datos->'items') loop insert into public.detalle_compra(id_compra,id_medicamento,cantidad,costo) values(id,(item->>'id_medicamento')::bigint,(item->>'cantidad')::int,(item->>'costo')::numeric);end loop;
 elsif p_accion='compra_recibir' then
  select * into c from public.compras where id_compra=(p_datos->>'id_compra')::bigint for update;if not found then raise exception 'Compra no encontrada' using errcode='P0002';end if;
  perform privado.exigir(array['GERENTE','BODEGA'],c.id_sucursal);if c.estado not in ('PENDIENTE','PARCIAL') then raise exception 'La compra ya no admite recepción' using errcode='P0001';end if;
  if c.factura is not null and c.factura<>p_datos->>'factura' then raise exception 'Usa la misma factura de la primera recepción' using errcode='P0001';end if;
  update public.compras set factura=p_datos->>'factura' where id_compra=c.id_compra;
  for item in select value from jsonb_array_elements(p_datos->'items') loop
   select * into dc from public.detalle_compra where id_compra=c.id_compra and id_medicamento=(item->>'id_medicamento')::bigint for update;
   if not found or (item->>'cantidad')::int>dc.cantidad-dc.recibido then raise exception 'La recepción excede la cantidad pendiente' using errcode='P0001';end if;
   perform privado.entrada(jsonb_build_object('id_sucursal',c.id_sucursal,'id_medicamento',dc.id_medicamento,'cantidad',(item->>'cantidad')::int,'costo_unitario',dc.costo,'lote',item->>'lote','fecha_vencimiento',item->>'fecha_vencimiento','motivo','Recepción compra #'||c.id_compra));
   update public.detalle_compra set recibido=recibido+(item->>'cantidad')::int where id_detalle=dc.id_detalle;
  end loop;
  update public.compras set estado=case when exists(select 1 from detalle_compra where id_compra=c.id_compra and recibido<cantidad) then 'PARCIAL' else 'RECIBIDA' end where id_compra=c.id_compra;id:=c.id_compra;
 elsif p_accion='compra_pagar' then
  select * into c from public.compras where id_compra=(p_datos->>'id_compra')::bigint for update;if not found then raise exception 'Compra no encontrada' using errcode='P0002';end if;
  perform privado.exigir(array['GERENTE','CAJERO'],c.id_sucursal);perform privado.exigir_permiso('confirmar_pago');
  select sum(recibido*costo) into monto from detalle_compra where id_compra=c.id_compra;
  if (p_datos->>'monto')::numeric>coalesce(monto,0)-c.pagado then raise exception 'El pago excede el saldo recibido pendiente' using errcode='P0001';end if;
  perform privado.caja(jsonb_build_object('id_sucursal',c.id_sucursal,'tipo','EGRESO','concepto','Pago compra #'||c.id_compra,'monto',(p_datos->>'monto')::numeric,'metodo_pago',p_datos->>'metodo_pago'));
  update public.compras set pagado=pagado+(p_datos->>'monto')::numeric where id_compra=c.id_compra;id:=c.id_compra;
 elsif p_accion='solicitar_ajuste' then
  select * into inv from inventario where id_inventario=(p_datos->>'id_inventario')::bigint;if not found then raise exception 'Lote no encontrado' using errcode='P0002';end if;perform privado.exigir(array['GERENTE','BODEGA'],inv.id_sucursal);
  insert into solicitudes_stock(id_sucursal,id_inventario,tipo,cantidad,existencia_observada,motivo,solicitado_por) values(inv.id_sucursal,inv.id_inventario,p_datos->>'tipo',(p_datos->>'cantidad')::int,inv.cantidad,p_datos->>'motivo',auth.uid()) returning id_solicitud into id;
 elsif p_accion='aprobar_ajuste' then
  select * into sol from solicitudes_stock where id_solicitud=(p_datos->>'id_solicitud')::bigint for update;if not found then raise exception 'Solicitud no encontrada' using errcode='P0002';end if;perform privado.exigir(array['GERENTE'],sol.id_sucursal);perform privado.exigir_permiso('aprobar_stock');if sol.estado<>'PENDIENTE' then raise exception 'Solicitud ya resuelta' using errcode='P0001';end if;
  if (p_datos->>'aprobar')::boolean then
   perform privado.bloquear_stock(sol.id_sucursal);select * into inv from inventario where id_inventario=sol.id_inventario for update;
   if sol.tipo='CONTEO' and inv.cantidad<>sol.existencia_observada then raise exception 'El inventario cambió después del conteo; registra un conteo nuevo' using errcode='P0001';end if;
   delta:=case when sol.tipo='CONTEO' then sol.cantidad-inv.cantidad else -sol.cantidad end;
   if delta<>0 then perform privado.ajuste(jsonb_build_object('id_inventario',inv.id_inventario,'diferencia',delta,'motivo',sol.tipo||': '||sol.motivo));end if;
  end if;
  update solicitudes_stock set estado=case when (p_datos->>'aprobar')::boolean then 'APROBADA' else 'RECHAZADA' end,aprobado_por=auth.uid() where id_solicitud=sol.id_solicitud;id:=sol.id_solicitud;
 elsif p_accion='devolucion_cliente' then
  select id_venta into id from detalle_venta where id_detalle=(p_datos->>'id_detalle')::bigint;select * into v from ventas where id_venta=id for update;if not found then raise exception 'Venta no encontrada' using errcode='P0002';end if;
  perform privado.exigir(array['GERENTE'],v.id_sucursal);perform privado.exigir_permiso('confirmar_pago');if v.estado<>'PAGADA' then raise exception 'La venta no admite devolución' using errcode='P0001';end if;
  select * into dv from detalle_venta where id_detalle=(p_datos->>'id_detalle')::bigint for update;
  if (p_datos->>'cantidad')::int>dv.cantidad-(select coalesce(sum(cantidad),0) from devoluciones_clientes where id_detalle=dv.id_detalle) then raise exception 'La devolución excede lo vendido pendiente de devolver' using errcode='P0001';end if;
  select coalesce(sum(subtotal),0) into neto from detalle_venta where id_venta=v.id_venta;select coalesce(costo_envio,0) into envio from pedidos where id_pedido=v.id_pedido;
  monto:=round(dv.precio_unitario*(p_datos->>'cantidad')::int*least(1,(v.total-coalesce(envio,0))/neto),2);
  insert into devoluciones_clientes(id_sucursal,id_detalle,cantidad,reembolso,motivo) values(v.id_sucursal,dv.id_detalle,(p_datos->>'cantidad')::int,monto,p_datos->>'motivo') returning id_devolucion into id;
  if monto>0 then perform privado.caja(jsonb_build_object('id_sucursal',v.id_sucursal,'tipo','EGRESO','concepto','Reembolso devolución #'||id,'monto',monto,'metodo_pago',p_datos->>'metodo_pago'));end if;
 elsif p_accion='cierre_caja' then
  sucursal:=(p_datos->>'id_sucursal')::bigint;perform privado.exigir(array['GERENTE','CAJERO'],sucursal);
  perform pg_advisory_xact_lock(7062100+sucursal);
  if (p_datos->>'hasta')::timestamptz>now() or (p_datos->>'hasta')::timestamptz<=(p_datos->>'desde')::timestamptz then raise exception 'Período de cierre inválido' using errcode='22023';end if;
  if exists(select 1 from cierres_caja where id_sucursal=sucursal and desde<(p_datos->>'hasta')::timestamptz and hasta>(p_datos->>'desde')::timestamptz) then raise exception 'Ya existe un cierre que se cruza con este período' using errcode='P0001';end if;
  select coalesce(sum(case when mc.tipo='INGRESO' then mc.monto else -mc.monto end),0) into monto from movimientos_caja mc where mc.id_sucursal=sucursal and mc.metodo_pago='EFECTIVO' and mc.fecha<(p_datos->>'hasta')::timestamptz;
  insert into cierres_caja(id_sucursal,desde,hasta,esperado,contado,diferencia,nota,creado_por) values(sucursal,(p_datos->>'desde')::timestamptz,(p_datos->>'hasta')::timestamptz,monto,(p_datos->>'contado')::numeric,(p_datos->>'contado')::numeric-monto,p_datos->>'nota',auth.uid()) returning id_cierre into id;
 elsif p_accion='cambiar_precio' then
  perform privado.exigir(array['GERENTE']);perform privado.exigir_permiso('modificar_precio');update medicamentos set precio_venta=(p_datos->>'precio_venta')::numeric where id_medicamento=(p_datos->>'id_medicamento')::bigint;get diagnostics delta=row_count;if delta=0 then raise exception 'Medicamento no encontrado' using errcode='P0002';end if;id:=(p_datos->>'id_medicamento')::bigint;
 else raise exception 'Operación desconocida' using errcode='22023';end if;
 resultado:=jsonb_build_object('id',id,'accion',p_accion);insert into privado.operaciones_farmacia values(p_clave,auth.uid(),p_accion,p_datos,resultado);return resultado;
end $$;
revoke all on function public.operar_farmacia(text,jsonb,uuid) from public,anon;
grant execute on function public.operar_farmacia(text,jsonb,uuid) to authenticated;
commit;
